`timescale 1ns/1ps
module tb_uart_tx; reg clk=0,rst_n=0,start=0; reg [7:0] data_in=8'h55; wire tx,busy; uart_tx #(.CLKS_PER_BIT(2)) dut(clk,rst_n,start,data_in,tx,busy); always #5 clk=~clk;
 initial begin rst_n=1; #2; rst_n=0; #1; if(tx!==1||busy!==0)$display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"reset\"}"); else $display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"reset\"}"); rst_n=1; @(negedge clk); start=1; @(negedge clk); start=0; if(!busy)$display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"start_busy\",\"signal\":\"busy\",\"expected\":1,\"actual\":%0d}",busy); else $display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"start_busy\"}"); repeat(25) @(negedge clk); if(busy)$display("IVERILOG_AI_RESULT {\"ok\":false,\"test_id\":\"complete\"}"); else $display("IVERILOG_AI_RESULT {\"ok\":true,\"test_id\":\"complete\"}"); $finish; end endmodule
